const menu=document.querySelector('#menu'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#project-type').value=a.dataset.service}));
const dialog=document.querySelector('#media-dialog'),body=document.querySelector('#dialog-body');let opener=null;
function closeDialog(){dialog.close();body.replaceChildren();document.body.style.overflow='';if(opener)opener.focus()}
document.querySelector('#close-dialog').addEventListener('click',closeDialog);dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
document.querySelectorAll('[data-video]').forEach(button=>button.addEventListener('click',()=>{opener=button;const title=document.createElement('h2');title.id='dialog-title';title.className='dialog-title';title.textContent=button.dataset.title;const frame=document.createElement('iframe');frame.className='video-frame';frame.src='https://player.vimeo.com/video/'+button.dataset.video+'?autoplay=1&dnt=1';frame.title=button.dataset.title;frame.allow='autoplay; fullscreen; picture-in-picture';frame.allowFullscreen=true;const link=document.createElement('a');link.className='video-fallback';link.href='https://vimeo.com/'+button.dataset.video;link.target='_blank';link.rel='noopener';link.textContent='Watch on Vimeo ↗';body.replaceChildren(title,frame,link);dialog.showModal();document.body.style.overflow='hidden'}));
const track=document.querySelector('#bts-track');function moveCarousel(direction){const step=track.querySelector('.bts-card').getBoundingClientRect().width;const max=track.scrollWidth-track.clientWidth;let next=direction>0?(track.scrollLeft>=max-10?0:Math.min(max,track.scrollLeft+step)):(track.scrollLeft<=10?max:Math.max(0,track.scrollLeft-step));track.scrollTo({left:next,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
document.querySelector('#bts-prev').addEventListener('click',()=>moveCarousel(-1));document.querySelector('#bts-next').addEventListener('click',()=>moveCarousel(1));track.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();moveCarousel(e.key==='ArrowRight'?1:-1)}});

let carouselVisible=false;const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');new IntersectionObserver(entries=>{carouselVisible=entries[0].isIntersecting},{threshold:.25}).observe(track);setInterval(()=>{if(carouselVisible&&!document.hidden&&!reducedMotion.matches&&!track.matches(':hover')&&!track.contains(document.activeElement))moveCarousel(1)},5000);

const extraFilms=[...document.querySelectorAll('.added-work')];let workShown=0;const loadWork=document.querySelector('#load-work');loadWork.addEventListener('click',()=>{const start=workShown;workShown=Math.min(workShown+4,extraFilms.length);extraFilms.slice(start,workShown).forEach(x=>x.hidden=false);document.querySelector('#work-count').textContent=(4+workShown)+' of '+(4+extraFilms.length)+' films';if(workShown===extraFilms.length){loadWork.hidden=true;extraFilms[start]?.focus()}});
